/**
 * Analytics period. `current` (default) and `previous` follow the household `monthStartDay`;
 * `YYYY-MM` selects the household month that starts in that calendar month; `YYYY-Www` selects an ISO week.
 *
 */
export const vPeriod = v.optional(v.pipe(v.string(), v.regex(/^(current|previous|\d{4}-\d{2}|\d{4}-W\d{2})$/)), 'current');

